+  assert.equal(wordCount('one\ntwo\tthree\r\nfour'), 4);
+});
+
+test('throws a TypeError naming the function for a non-string', () => {
+  for (const bad of [undefined, null, 42, {}, [], ['a b']]) {
+    assert.throws(() => wordCount(bad), (err) => {
+      assert.ok(err instanceof TypeError);
+      assert.ok(err.message.startsWith('wordCount:'));
+      return true;
+    });
+  }
+});
+
+test('matches every row of the reference table', () => {
+  for (const [text, expected] of CASES) {
+    assert.equal(wordCount(text), expected, JSON.stringify(text));
+  }
+});
+
+test('counts the 64 words of a multi-line passage with ordinary punctuation.', () => {
+  assert.equal(wordCount(PASSAGE), 64);
+});
+
+test('joins a straight or typographic apostrophe between letters into one word', () => {
+  assert.equal(wordCount("don't"), 1);
+  assert.equal(wordCount('keeper’s'), 1);
+  assert.equal(wordCount("don't stop"), 2);
+});
+
+test('joins a single hyphen between letters into one word', () => {
+  assert.equal(wordCount('well-known'), 1);
+  assert.equal(wordCount('well-known fact'), 2);
+});
+
+test('drops a stray trailing joiner instead of counting it or splitting the word', () => {
+  assert.equal(wordCount('well-'), 1);
+  assert.equal(wordCount('dogs\''), 1);
+  assert.equal(wordCount('dogs’'), 1);
+  assert.equal(wordCount('well- done'), 2);
+});
+
+test('does not join across a doubled joiner', () => {
+  assert.equal(wordCount('a--b'), 2);
+  assert.equal(wordCount("a''b"), 2);
+  assert.equal(wordCount('a’’b'), 2);
+});
+
+test('separates words at em dashes, en dashes, slashes and underscores', () => {
+  assert.equal(wordCount('a—b'), 2);
+  assert.equal(wordCount('a–b'), 2);
+  assert.equal(wordCount('and/or'), 2);
+  assert.equal(wordCount('snake_case'), 2);
+});
+
+test('separates words at the point in a decimal number or domain name', () => {
+  assert.equal(wordCount('3.14'), 2);
+  assert.equal(wordCount('example.com'), 2);
+});
+
+test('counts words and digits in non-Latin and accented scripts', () => {
+  assert.equal(wordCount('café'), 1);
+  assert.equal(wordCount('naïve'), 1);
+  assert.equal(wordCount('Привет'), 1);
+  assert.equal(wordCount('καλημέρα κόσμε'), 2);
+  assert.equal(wordCount('2024'), 1);
+});
+
+test('returns 0 for a long string made only of punctuation and symbols', () => {
+  assert.equal(wordCount('!?.,;:—–-\'’/_ '.repeat(200)), 0);
+});
